s = replace_once(s, "    Unauthorized,\n    UnsupportedSchemaVersion,", "    Unauthorized,\n    Forbidden,\n    UnsupportedSchemaVersion,", "protocol enum")
s = replace_once(s, "            ErrorCode::Unauthorized => \"unauthorized\",\n            ErrorCode::UnsupportedSchemaVersion", "            ErrorCode::Unauthorized => \"unauthorized\",\n            ErrorCode::Forbidden => \"forbidden\",\n            ErrorCode::UnsupportedSchemaVersion", "protocol string")
s = replace_once(s, "            \"unauthorized\" => Ok(ErrorCode::Unauthorized),\n            \"unsupported_schema_version\"", "            \"unauthorized\" => Ok(ErrorCode::Unauthorized),\n            \"forbidden\" => Ok(ErrorCode::Forbidden),\n            \"unsupported_schema_version\"", "protocol decode")
s = replace_once(s, "                    \"unauthorized\",\n                    \"unsupported_schema_version\",", "                    \"unauthorized\",\n                    \"forbidden\",\n                    \"unsupported_schema_version\",", "protocol variants")
p.write_text(s)

# hub-api: principal-backed middleware while preserving legacy builder.
p = Path("crates/hub-api/src/lib.rs")
s = p.read_text()
s = replace_once(s, "mod metrics;\n", "mod auth;\nmod metrics;\n\npub use auth::{AuthConfigError, AuthPermission, AuthenticatedPrincipal, StaticPrincipal};\n", "api module")
s = replace_once(s, "use sha2::{Digest, Sha256};\n", "", "api sha import")
s = replace_once(s, "    api_bearer_sha256: Option<[u8; 32]>,", "    api_principals: Vec<StaticPrincipal>,", "api state field")
s = replace_once(s, "            api_bearer_sha256: None,", "            api_principals: Vec::new(),", "api state init")
old = '''    pub fn with_bearer_token(mut self, token: impl AsRef<str>) -> Result<Self, EmptyBearerToken> {\n        let token = token.as_ref();\n        if token.is_empty() {\n            return Err(EmptyBearerToken);\n        }\n        self.api_bearer_sha256 = Some(Sha256::digest(token.as_bytes()).into());\n        Ok(self)\n    }\n'''
new = '''    pub fn with_bearer_token(mut self, token: impl AsRef<str>) -> Result<Self, EmptyBearerToken> {\n        let token = token.as_ref();\n        if token.is_empty() {\n            return Err(EmptyBearerToken);\n        }\n        let principal = StaticPrincipal::new(\n            "legacy-control",\n            token,\n            AuthPermission::ALL,\n        )\n        .map_err(|_| EmptyBearerToken)?;\n        self.api_principals = vec![principal];\n        Ok(self)\n    }\n\n    /// Enables explicit static-principal authorization. This replaces legacy\n    /// single-token mode for this state instance.\n    ///\n    /// # Errors\n    /// Fails closed for an empty set, duplicate ids, or duplicate credentials.\n    pub fn with_static_principals(\n        mut self,\n        principals: Vec<StaticPrincipal>,\n    ) -> Result<Self, AuthConfigError> {\n        auth::validate_static_principals(&principals)?;\n        self.api_principals = principals;\n        Ok(self)\n    }\n'''
s = replace_once(s, old, new, "legacy builder")
old = '''async fn require_api_bearer(\n    State(state): State<HubState>,\n    request: Request,\n    next: Next,\n) -> Response {\n    let Some(expected) = state.api_bearer_sha256 else {\n        return next.run(request).await;\n    };\n    let supplied = request\n        .headers()\n        .get(header::AUTHORIZATION)\n        .and_then(|value| value.to_str().ok())\n        .and_then(|value| value.strip_prefix("Bearer "))\n        .filter(|value| !value.is_empty())\n        .map(|token| <[u8; 32]>::from(Sha256::digest(token.as_bytes())));\n    if supplied.is_some_and(|actual| digest_eq(&expected, &actual)) {\n        return next.run(request).await;\n    }\n\n    let mut response = error_response(\n        StatusCode::UNAUTHORIZED,\n        proto::ErrorCode::Unauthorized,\n        "bearer authentication required",\n    );\n    response\n        .headers_mut()\n        .insert(header::WWW_AUTHENTICATE, HeaderValue::from_static("Bearer"));\n    response\n}\n\nfn digest_eq(left: &[u8; 32], right: &[u8; 32]) -> bool {\n    let mut difference = 0u8;\n    for (&a, &b) in left.iter().zip(right.iter()) {\n        difference |= a ^ b;\n    }\n    difference == 0\n}\n'''
new = '''async fn require_api_bearer(\n    State(state): State<HubState>,\n    mut request: Request,\n    next: Next,\n) -> Response {\n    if state.api_principals.is_empty() {\n        return next.run(request).await;\n    }\n    let supplied = request\n        .headers()\n        .get(header::AUTHORIZATION)\n        .and_then(|value| value.to_str().ok())\n        .and_then(|value| value.strip_prefix("Bearer "))\n        .filter(|value| !value.is_empty());\n    let Some(principal) = supplied.and_then(|token| auth::authenticate(&state.api_principals, token)) else {\n        let mut response = error_response(\n            StatusCode::UNAUTHORIZED,\n            proto::ErrorCode::Unauthorized,\n            "bearer authentication required",\n        );\n        response\n            .headers_mut()\n            .insert(header::WWW_AUTHENTICATE, HeaderValue::from_static("Bearer"));\n        return response;\n    };\n\n    let method = request.method().clone();\n    let path = request.uri().path().to_owned();\n    let required = auth::required_permission(&method, &path);\n    if !principal.permits(required) {\n        return error_response(\n            StatusCode::FORBIDDEN,\n            proto::ErrorCode::Forbidden,\n            "authenticated principal lacks required permission",\n        );\n    }\n\n    let identity = principal.authenticated_identity();\n    let principal_id = identity.id().to_owned();\n    request.extensions_mut().insert(identity);\n    let response = next.run(request).await;\n    if required == AuthPermission::Control && response.status().is_success() {\n        tracing::info!(\n            principal_id = %principal_id,\n            method = %method,\n            path = %path,\n            status = response.status().as_u16(),\n            "authorized control-plane mutation completed"\n        );\n    }\n    response\n}\n'''
s = replace_once(s, old, new, "api middleware")
anchor = '''    #[test]\n    fn empty_bearer_token_is_rejected() {\n'''
test = '''    #[tokio::test]\n    async fn static_principals_distinguish_authentication_authorization_and_metrics() {\n        let (state, _clock, _dir) = test_state();\n        let observer = StaticPrincipal::new(\n            "observer",\n            "observer-secret",\n            [AuthPermission::Inspect, AuthPermission::Metrics],\n        )\n        .expect("observer");\n        let controller = StaticPrincipal::new(\n            "controller",\n            "controller-secret",\n            AuthPermission::ALL,\n        )\n        .expect("controller");\n        let app = router(\n            state\n                .with_static_principals(vec![observer, controller])\n                .expect("principal set"),\n        );\n\n        let (status, body) = send(\n            app.clone(),\n            Request::builder()\n                .uri("/api/v1/components")\n                .header("authorization", "Bearer wrong")\n                .body(Body::empty())\n                .expect("req"),\n        )\n        .await;\n        assert_eq!(status, StatusCode::UNAUTHORIZED);\n        assert_eq!(body["error"]["code"], "unauthorized");\n\n        let (status, _) = send(\n            app.clone(),\n            Request::builder()\n                .uri("/api/v1/components")\n                .header("authorization", "Bearer observer-secret")\n                .body(Body::empty())\n                .expect("req"),\n        )\n        .await;\n        assert_eq!(status, StatusCode::OK);\n\n        let response = app\n            .clone()\n            .oneshot(\n                Request::builder()\n                    .uri("/metrics")\n                    .header("authorization", "Bearer observer-secret")\n                    .body(Body::empty())\n                    .expect("req"),\n            )\n            .await\n            .expect("metrics");\n        assert_eq!(response.status(), StatusCode::OK);\n\n        let observer_mutation = Request::builder()\n            .method("POST")\n            .uri("/api/v1/components")\n            .header("authorization", "Bearer observer-secret")\n            .header("x-scirust-hub-principal", "controller")\n            .header("content-type", "application/json")\n            .body(Body::from(sample_manifest_json()))\n            .expect("req");\n        let (status, body) = send(app.clone(), observer_mutation).await;\n        assert_eq!(status, StatusCode::FORBIDDEN);\n        assert_eq!(body["error"]["code"], "forbidden");\n\n        let controller_mutation = Request::builder()\n            .method("POST")\n            .uri("/api/v1/components")\n            .header("authorization", "Bearer controller-secret")\n            .header("content-type", "application/json")\n            .body(Body::from(sample_manifest_json()))\n            .expect("req");\n        let (status, _) = send(app, controller_mutation).await;\n        assert_eq!(status, StatusCode::CREATED);\n    }\n\n'''
s = replace_once(s, anchor, test + anchor, "api authz test")
p.write_text(s)

# hubd: strict versioned JSON config and legacy mutual exclusion.
p = Path("apps/scirust-hubd/src/main.rs")
s = p.read_text()
s = replace_once(s, "use hub_api::HubState;", "use hub_api::{AuthPermission, HubState, StaticPrincipal};", "hubd import")
s = replace_once(s, "const REMOTE_WORKER_TOKENS_JSON_ENV: &str = \"SCIRUST_HUB_REMOTE_WORKER_TOKENS_JSON\";", "const REMOTE_WORKER_TOKENS_JSON_ENV: &str = \"SCIRUST_HUB_REMOTE_WORKER_TOKENS_JSON\";\nconst PRINCIPALS_JSON_ENV: &str = \"SCIRUST_HUB_PRINCIPALS_JSON\";", "hubd env const")
old = '''    let api_token = std::env::var("SCIRUST_HUB_TOKEN")\n        .ok()\n        .filter(|token| !token.is_empty());\n    let tls = tls_files(args.tls_cert, args.tls_key)?;\n    validate_control_plane_security(listen, api_token.as_deref())?;\n'''
new = '''    let api_token = std::env::var("SCIRUST_HUB_TOKEN")\n        .ok()\n        .filter(|token| !token.is_empty());\n    let principals_json = std::env::var(PRINCIPALS_JSON_ENV)\n        .ok()\n        .filter(|value| !value.trim().is_empty());\n    if api_token.is_some() && principals_json.is_some() {\n        return Err(DaemonError::SecurityConfig(format!(\n            "SCIRUST_HUB_TOKEN and {PRINCIPALS_JSON_ENV} are mutually exclusive"\n        )));\n    }\n    let static_principals = parse_static_principals(principals_json.as_deref())?;\n    let tls = tls_files(args.tls_cert, args.tls_key)?;\n    validate_control_plane_security(\n        listen,\n        api_token.is_some() || static_principals.is_some(),\n    )?;\n'''
s = replace_once(s, old, new, "hubd auth load")
old = '''        if let Some(token) = api_token {\n            state = state\n                .with_bearer_token(token)\n                .map_err(|error| DaemonError::SecurityConfig(error.to_string()))?;\n        }\n'''
new = '''        if let Some(principals) = static_principals {\n            state = state\n                .with_static_principals(principals)\n                .map_err(|error| DaemonError::SecurityConfig(error.to_string()))?;\n        } else if let Some(token) = api_token {\n            state = state\n                .with_bearer_token(token)\n                .map_err(|error| DaemonError::SecurityConfig(error.to_string()))?;\n        }\n'''
s = replace_once(s, old, new, "hubd state auth")
old = '''fn validate_control_plane_security(\n    listen: SocketAddr,\n    api_token: Option<&str>,\n) -> Result<(), DaemonError> {\n    if !listen.ip().is_loopback() && api_token.is_none() {\n        return Err(DaemonError::SecurityConfig(format!(\n            "refusing unauthenticated non-loopback bind {listen}; set SCIRUST_HUB_TOKEN"\n        )));\n    }\n    Ok(())\n}\n'''
new = '''fn validate_control_plane_security(\n    listen: SocketAddr,\n    authentication_configured: bool,\n) -> Result<(), DaemonError> {\n    if !listen.ip().is_loopback() && !authentication_configured {\n        return Err(DaemonError::SecurityConfig(format!(\n            "refusing unauthenticated non-loopback bind {listen}; set SCIRUST_HUB_TOKEN or {PRINCIPALS_JSON_ENV}"\n        )));\n    }\n    Ok(())\n}\n\nfn parse_static_principals(raw: Option<&str>) -> Result<Option<Vec<StaticPrincipal>>, DaemonError> {\n    let Some(raw) = raw else {\n        return Ok(None);\n    };\n    let value: serde_json::Value = serde_json::from_str(raw).map_err(|error| {\n        DaemonError::SecurityConfig(format!("invalid {PRINCIPALS_JSON_ENV} JSON: {error}"))\n    })?;\n    let root = value.as_object().ok_or_else(|| {\n        DaemonError::SecurityConfig(format!("{PRINCIPALS_JSON_ENV} must be a JSON object"))\n    })?;\n    for key in root.keys() {\n        if !matches!(key.as_str(), "schema_version" | "principals") {\n            return Err(DaemonError::SecurityConfig(format!(\n                "unknown {PRINCIPALS_JSON_ENV} field {key:?}"\n            )));\n        }\n    }\n    if root.get("schema_version").and_then(serde_json::Value::as_u64) != Some(1) {\n        return Err(DaemonError::SecurityConfig(format!(\n            "{PRINCIPALS_JSON_ENV} requires schema_version 1"\n        )));\n    }\n    let records = root\n        .get("principals")\n        .and_then(serde_json::Value::as_array)\n        .ok_or_else(|| {\n            DaemonError::SecurityConfig(format!(\n                "{PRINCIPALS_JSON_ENV}.principals must be an array"\n            ))\n        })?;\n    let mut principals = Vec::with_capacity(records.len());\n    for record in records {\n        let object = record.as_object().ok_or_else(|| {\n            DaemonError::SecurityConfig("each static principal must be a JSON object".into())\n        })?;\n        for key in object.keys() {\n            if !matches!(key.as_str(), "id" | "token" | "permissions") {\n                return Err(DaemonError::SecurityConfig(format!(\n                    "unknown static principal field {key:?}"\n                )));\n            }\n        }\n        let id = object\n            .get("id")\n            .and_then(serde_json::Value::as_str)\n            .ok_or_else(|| DaemonError::SecurityConfig("static principal id must be a string".into()))?;\n        let token = object\n            .get("token")\n            .and_then(serde_json::Value::as_str)\n            .ok_or_else(|| {\n                DaemonError::SecurityConfig(format!(\n                    "static principal {id:?} token must be a string"\n                ))\n            })?;\n        let permission_values = object\n            .get("permissions")\n            .and_then(serde_json::Value::as_array)\n            .ok_or_else(|| {\n                DaemonError::SecurityConfig(format!(\n                    "static principal {id:?} permissions must be an array"\n                ))\n            })?;\n        let mut permissions = Vec::with_capacity(permission_values.len());\n        for permission in permission_values {\n            let raw_permission = permission.as_str().ok_or_else(|| {\n                DaemonError::SecurityConfig(format!(\n                    "static principal {id:?} permission must be a string"\n                ))\n            })?;\n            permissions.push(AuthPermission::parse(raw_permission).ok_or_else(|| {\n                DaemonError::SecurityConfig(format!(\n                    "unknown static principal permission {raw_permission:?} for {id:?}"\n                ))\n            })?);\n        }\n        principals.push(\n            StaticPrincipal::new(id, token, permissions)\n                .map_err(|error| DaemonError::SecurityConfig(error.to_string()))?,\n        );\n    }\n    hub_api::validate_static_principals(&principals)\n        .map_err(|error| DaemonError::SecurityConfig(error.to_string()))?;\n    Ok(Some(principals))\n}\n'''
s = replace_once(s, old, new, "hubd security helpers")
# Update existing security tests call shape if present.
s = s.replace("validate_control_plane_security(loopback, None)", "validate_control_plane_security(loopback, false)")
s = s.replace("validate_control_plane_security(non_loopback, None)", "validate_control_plane_security(non_loopback, false)")
s = s.replace("validate_control_plane_security(non_loopback, Some(\"secret\"))", "validate_control_plane_security(non_loopback, true)")
anchor = '''    #[test]\n    fn rustls_crypto_provider_is_installed_explicitly() {\n'''
test = '''    #[test]\n    fn versioned_static_principal_config_is_strict_and_secret_safe() {\n        let raw = r#"{\"schema_version\":1,\"principals\":[{\"id\":\"observer\",\"token\":\"secret-a\",\"permissions\":[\"inspect\",\"metrics\"]},{\"id\":\"controller\",\"token\":\"secret-b\",\"permissions\":[\"inspect\",\"control\",\"metrics\"]}]}"#;\n        let principals = parse_static_principals(Some(raw))\n            .expect("valid")\n            .expect("configured");\n        assert_eq!(principals.len(), 2);\n        assert_eq!(principals[0].id(), "observer");\n\n        let unknown = r#"{\"schema_version\":1,\"principals\":[{\"id\":\"observer\",\"token\":\"secret-a\",\"permissions\":[\"admin\"]}]}"#;\n        assert!(parse_static_principals(Some(unknown)).is_err());\n        let duplicate_id = r#"{\"schema_version\":1,\"principals\":[{\"id\":\"same\",\"token\":\"secret-a\",\"permissions\":[\"inspect\"]},{\"id\":\"same\",\"token\":\"secret-b\",\"permissions\":[\"control\"]}]}"#;\n        assert!(parse_static_principals(Some(duplicate_id)).is_err());\n        let duplicate_token = r#"{\"schema_version\":1,\"principals\":[{\"id\":\"a\",\"token\":\"same-secret\",\"permissions\":[\"inspect\"]},{\"id\":\"b\",\"token\":\"same-secret\",\"permissions\":[\"control\"]}]}"#;\n        assert!(parse_static_principals(Some(duplicate_token)).is_err());\n    }\n\n'''
s = replace_once(s, anchor, test + anchor, "hubd principal tests")
